//
//  TransportLexicon.swift
//  EusoTrip — Mode-aware freight terminology lexicon.
//
//  GENERATED (do not hand-edit the embedded data) from a 63-agent research
//  fan-out across 8 transport sub-modes × 7 concept domains (schedule, locations,
//  parties, documents, charges, equipment, status). 447 canonical concepts.
//  Sources: BIMCO/charter-party, Hague-Visby, AAR, FMCSA, IMO/IMDG, SOLAS VGM,
//  US STB, INCOTERMS 2020, UN/CEFACT. Readable form:
//  _the_oath_reports/_MODE_TERMINOLOGY_LEXICON_2026-06-03.json
//
//  Why: the same concept is named differently per mode — a vessel "pickup window"
//  is a LAYCAN (laydays + cancelling) tendered via NOR; rail uses constructive
//  placement / ramp cutoff; truck uses the pickup appointment / detention. The app
//  must speak each mode's native language. Resolve with `TransportLexicon.term(...)`.
//

import Foundation

/// The 8 fine-grained sub-modes the lexicon distinguishes (finer than the 4-case
/// `TransportMode`). Resolved from a `TransportMode` + equipment hint.
public enum LexMode: String, CaseIterable, Sendable {
    case truckFTL        = "truck_ftl"
    case truckBulkLTL    = "truck_bulk_ltl"
    case drayage         = "drayage"
    case railCarload     = "rail_carload"
    case railIntermodal  = "rail_intermodal"
    case oceanContainer  = "ocean_container"
    case oceanBulkTanker = "ocean_bulk_tanker"
    case bargeBreakbulk  = "barge_breakbulk"
}

/// Typed handles for the concepts wired into UI today. The full 447-concept
/// table is reachable by raw key via `TransportLexicon.term(key:...)`.
public enum TransportConcept: String, Sendable {
    case originWindow = "originWindow"
    case destinationWindow = "destinationWindow"
    case laycan = "laycan"
    case cancellingDate = "cancellingDate"
    case readinessNotice = "readinessNotice"
    case noticeOfReadiness = "noticeOfReadiness"
    case appointment = "appointment"
    case mustArriveBy = "mustArriveBy"
    case freeTime = "freeTime"
    case lastFreeDay = "lastFreeDay"
    case detention = "detention"
    case demurrage = "demurrage"
    case despatch = "despatch"
    case storage = "storage"
    case perDiem = "perDiem"
    case billOfLading = "billOfLading"
    case proofOfDelivery = "proofOfDelivery"
    case consignee = "consignee"
    case loaded = "loaded"
    case departed = "departed"
    case unloaded = "unloaded"
    case delivered = "delivered"
    case primarySafetyAuthority = "primarySafetyAuthority"
    case carrierSafetyRegistry = "carrierSafetyRegistry"
    case commercialVettingRating = "commercialVettingRating"
    case safetyRating = "safetyRating"
    case operatingAuthority = "operatingAuthority"
    case hazmatRegime = "hazmatRegime"
    case hazmatCarrierPermit = "hazmatCarrierPermit"
    case cargoInsurance = "cargoInsurance"
    case liabilityInsuranceFiling = "liabilityInsuranceFiling"
    case customsBorderFiling = "customsBorderFiling"
    case inspectionRegime = "inspectionRegime"
    case emissionsEnvironmentalRegime = "emissionsEnvironmentalRegime"
}

public struct LexTerm: Sendable {
    public let term: String
    public let abbreviation: String
    public let short: String
}

public struct LexEntry: Sendable {
    public let generic: String
    public let shortGeneric: String
    public let byMode: [String: LexTerm]
}

public enum TransportLexicon {

    // Base64-encoded JSON (escaping-safe, type-checks instantly, parsed once).
    private static let encoded = ""

    /// Parsed concept table, decoded + cached on first access.
    public static let entries: [String: LexEntry] = decodeEntries()

    private static func decodeEntries() -> [String: LexEntry] {
        guard let data = Data(base64Encoded: encoded),
              let raw = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return [:]
        }
        var out: [String: LexEntry] = [:]
        out.reserveCapacity(raw.count)
        for (key, v) in raw {
            guard let obj = v as? [String: Any] else { continue }
            let generic = obj["g"] as? String ?? ""
            let shortGeneric = obj["sg"] as? String ?? ""
            var byMode: [String: LexTerm] = [:]
            if let m = obj["m"] as? [String: [String]] {
                for (mode, arr) in m {
                    byMode[mode] = LexTerm(
                        term: arr.indices.contains(0) ? arr[0] : "",
                        abbreviation: arr.indices.contains(1) ? arr[1] : "",
                        short: arr.indices.contains(2) ? arr[2] : ""
                    )
                }
            }
            out[key] = LexEntry(generic: generic, shortGeneric: shortGeneric, byMode: byMode)
        }
        return out
    }

    // MARK: - Mode resolution

    /// Resolve the app's 4-case `TransportMode` (+ optional equipment hint, e.g. an
    /// EquipmentChoice rawValue like "vesselBulk" / "railIntermodal" / "tankerPetro")
    /// down to one of the 8 lexicon sub-modes.
    public static func lexMode(_ mode: TransportMode, equipmentRaw: String? = nil) -> LexMode {
        let eq = (equipmentRaw ?? "").lowercased()
        func has(_ s: String) -> Bool { eq.contains(s) }
        switch mode {
        case .truck:
            if has("tanker") || has("bulk") || has("pneumatic") || has("ltl") { return .truckBulkLTL }
            if has("container") || has("drayage") || has("intermodal") || has("chassis") { return .drayage }
            return .truckFTL
        case .rail:
            if has("intermodal") || has("tofc") || has("cofc") || has("doublestack") { return .railIntermodal }
            return .railCarload
        case .vessel:
            if has("bulk") || has("tanker") || has("lng") || has("iso") { return .oceanBulkTanker }
            if has("roro") || has("ro-ro") || has("breakbulk") { return .bargeBreakbulk }
            return .oceanContainer
        case .barge:
            return .bargeBreakbulk
        }
    }

    // MARK: - Lookups (mode-correct, with graceful fallback to the generic label)

    public static func term(key: String, mode: TransportMode, equipmentRaw: String? = nil) -> String {
        guard let e = entries[key] else { return "" }
        let lm = lexMode(mode, equipmentRaw: equipmentRaw).rawValue
        if let t = e.byMode[lm]?.term, !t.isEmpty { return t }
        return e.generic
    }
    public static func term(_ c: TransportConcept, mode: TransportMode, equipmentRaw: String? = nil) -> String {
        term(key: c.rawValue, mode: mode, equipmentRaw: equipmentRaw)
    }

    /// Compact form for chips/labels — falls back short→term→shortGeneric→generic.
    public static func short(key: String, mode: TransportMode, equipmentRaw: String? = nil) -> String {
        guard let e = entries[key] else { return "" }
        let lm = lexMode(mode, equipmentRaw: equipmentRaw).rawValue
        if let t = e.byMode[lm] {
            if !t.short.isEmpty { return t.short }
            if !t.term.isEmpty { return t.term }
        }
        return e.shortGeneric.isEmpty ? e.generic : e.shortGeneric
    }
    public static func short(_ c: TransportConcept, mode: TransportMode, equipmentRaw: String? = nil) -> String {
        short(key: c.rawValue, mode: mode, equipmentRaw: equipmentRaw)
    }

    public static func abbreviation(key: String, mode: TransportMode, equipmentRaw: String? = nil) -> String {
        guard let e = entries[key] else { return "" }
        let lm = lexMode(mode, equipmentRaw: equipmentRaw).rawValue
        return e.byMode[lm]?.abbreviation ?? ""
    }

    public static func generic(key: String) -> String { entries[key]?.generic ?? "" }
}
